describe('Onboarding Tour Modal - Step Advancement', () => {
  beforeEach(() => {
    cy.visit('/onboarding');
  });

  it('should advance through onboarding tour steps using next button', () => {
    // Verify modal is visible
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');

    // Verify first step is displayed
    cy.get('[data-testid="onboarding-step-1-title"]').should('contain', 'Welcome to the App');
    cy.get('[data-testid="onboarding-step-1-description"]').should('be.visible');

    // Click next button to advance to step 2
    cy.get('[data-testid="onboarding-next-button"]').click();

    // Verify step 2 is displayed
    cy.get('[data-testid="onboarding-step-2-title"]').should('be.visible');
    cy.get('[data-testid="onboarding-step-2-description"]').should('contain', 'Explore the dashboard');

    // Click next button to advance to step 3
    cy.get('[data-testid="onboarding-next-button"]').click();

    // Verify step 3 is displayed
    cy.get('[data-testid="onboarding-step-3-title"]').should('be.visible');
    cy.get('[data-testid="onboarding-step-3-description"]').should('contain', 'Customize your profile');

    // Click finish button to complete tour
    cy.get('[data-testid="onboarding-finish-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.exist');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });

  it('should handle edge case of clicking next button when on last step', () => {
    // Open onboarding modal
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');

    // Advance to last step (step 3)
    cy.get('[data-testid="onboarding-next-button"]').click();
    cy.get('[data-testid="onboarding-step-2-title"]').should('be.visible');
    cy.get('[data-testid="onboarding-next-button"]').click();
    cy.get('[data-testid="onboarding-step-3-title"]').should('be.visible');

    // Verify finish button is visible on last step
    cy.get('[data-testid="onboarding-finish-button"]').should('be.visible');

    // Verify next button is disabled or hidden on last step
    cy.get('[data-testid="onboarding-next-button"]').should('be.disabled');

    // Attempt to click disabled next button (should not advance)
    cy.get('[data-testid="onboarding-next-button"]').click({ force: true });

    // Verify still on step 3
    cy.get('[data-testid="onboarding-step-3-title"]').should('be.visible');

    // Click finish button
    cy.get('[data-testid="onboarding-finish-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.exist');
  });
});
